__attribute__((target("avx2,fma")))
void radix15_z_msg_bwd_avx2(
    const double *            zin,
    const double *            zin_unused,
    double       *            zout,
    double       *            zout_unused,
    const double * tw_re, const double * tw_im,
    size_t Ls, size_t Gs, size_t OLs, size_t OGs, size_t count)
{
    (void)zin; (void)zin_unused; (void)zout_unused; (void)tw_im;
    (void)OLs; (void)OGs;
    double *bp = zout;
    const double *twg = tw_re;
    for (size_t g = 0; g < Gs; g++) {
        _zsg15b_body(bp, bp, twg, Ls, count);
        bp += 2 * (size_t)15 * Ls;
        twg += 112;
    }
}
